function runsHtml(runs){return runs.map(r=>r.kind==='text'?esc(r.text):`<button class="marker" data-note="${esc(r.text)}" aria-label="展开此处注释">〔注〕</button><span class="note">${esc(r.text)}</span>`).join('');}
function paragraphs(ps){return ps.map((p,i)=>`<p id="para-${i}" class="${/^(臣光曰|太史公曰)/.test(p.plain)?'commentary':''}">${runsHtml(p.runs)}</p>`).join('');}
let readingMode='compare',yearbookScroll=0,readerReturnState;
function enterReadingPage(){if(!readerOpen){yearbookScroll=window.scrollY;focusBefore=document.activeElement;}readerOpen=true;$('#annualPage').classList.add('hidden');$('#readerBackdrop').classList.remove('hidden');document.body.style.overflow='';}
function updateRoute(hash){if(location.hash!==hash)history.pushState({reading:true},'',hash);}

function setReadingMode(mode){readingMode=mode;$('#readerScroll').classList.toggle('mode-original',mode==='original');$('#readerScroll').classList.toggle('mode-modern',mode==='modern');$('#readerScroll').classList.toggle('mode-immersive',mode==='immersive');document.querySelectorAll('[data-reading-mode]').forEach(x=>x.classList.toggle('active',x.dataset.readingMode===mode));$('#showNotes').disabled=mode==='modern';$('#showNotes').closest('label').classList.toggle('dim',mode==='modern');}
function pairedRows(y){const pairs=[...y.bilingual.filter(p=>!p.difference),...y.translationMissing.map(i=>({huIndices:[i],modern:y.paragraphs[i].structural?'原书年号衔接，非记事正文。':'上传译本未提供或未能可靠对应本段白话。原文完整保留，等待补充校对。',kind:'record',missing:true}))].sort((a,b)=>a.huIndices[0]-b.huIndices[0]);return pairs.map((pair,k)=>`<section class="compare-row" tabindex="0" aria-label="第${k+1}组原文白话对照" data-pair="${k}"><div class="original-cell"><span class="row-index">${String(k+1).padStart(2,'0')}</span><span class="mobile-label">原文 · 胡三省注本</span>${pair.kind==='commentary'?'<span class="kind-label">史家评论 · 原文</span>':''}<div class="original ${$('#showNotes').checked?'':'hide-notes'}">${pair.huIndices.map(i=>`<p id="para-${i}">${runsHtml(y.paragraphs[i].runs)}</p>`).join('')}</div></div><div class="translation-cell"><span class="row-index">${String(k+1).padStart(2,'0')}</span><span class="mobile-label">白话 · 上传柏杨版</span>${pair.kind==='commentary'?'<span class="kind-label">史家评论 · 白话译文</span>':''}${pair.reviewStatus==='check-source'?'<span class="reading-hint">两版字句有差异，建议核对原文。</span>':''}<p class="modern-text">${pair.modern.split('\n').map(t=>esc(t.replace(/^\[\d+\]/,''))).join('<br><br>')}</p></div></section>`).join('');}
