function readYear(year,anchor=null,updateHistory=true){hidePeoplePage();enterReadingPage();selected=year;readingIndex=book.years.findIndex(y=>y.year===year);const y=book.years[readingIndex];$('#readerYear').value=year;$('#readerContent').innerHTML=`<div class="reader-inner"><div class="reader-title"><div class="eyebrow">${yearLabel(y.year)} · ${esc(bookLabel())}</div><h2>${esc(reign(y))}</h2><div class="reign-line">${y.recorded?'原文与白话，逐段对读':'本卷未单列此年记事'}</div><div class="meta">胡三省注本原文 × 上传柏杨版白话 · ${y.bilingual.filter(p=>!p.difference).length} 组对照</div></div>${y.headingRuns?`<div class="original source-heading ${$('#showNotes').checked?'':'hide-notes'}"><p>${runsHtml(y.headingRuns)}</p></div>`:''}${y.warning?`<div class="year-note">版本提示：${esc(y.warning)}</div>`:''}${y.translationWarning?`<div class="year-note">${esc(y.translationWarning)}</div>`:''}${y.noteWarning?`<div class="year-note">${esc(y.noteWarning)}</div>`:''}${yearParts(y)}${y.translationMissing.some(i=>!y.paragraphs[i].structural)?'<div class="year-note">本年部分段落缺少可靠对应译文，右栏已逐段标注；未自行补写为上传版译文。</div>':''}${y.year===403?'<div class="year-note">本年包含智氏覆亡、晋阳之战等更早事件的追叙，以及史家评论。这里保留胡注本正文次序，不将追叙改列为当年事件。</div>':''}${y.recorded?`<div class="column-labels"><div class="original-label">原文<small>司马光 · 胡三省注本</small></div><div class="translation-label">白话译文<small>上传柏杨版文件</small></div></div><article class="comparison">${pairedRows(y)}</article>${versionDifferences(y)}${unparsedTranslation(y)}`:'<p class="empty-reading">胡注本未在本卷单列这一年的记事。可切换前后年份继续阅读。</p>'}${y.after.length?`<div class="source-transition original ${$('#showNotes').checked?'':'hide-notes'}"><span class="reading-hint">原书衔接 · 下一君主年号</span>${y.after.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}</div>`;setReadingMode(readingMode);window.scrollTo({top:0,behavior:'instant'});$('#progressBar').style.width='0';updateYearNavigation();document.querySelectorAll('[data-jump]').forEach(b=>b.classList.toggle('active',+b.dataset.jump===year));if(anchor!==null)requestAnimationFrame(()=>{const p=$('#para-'+anchor);if(p){const row=p.closest('.compare-row');if(row){row.scrollIntoView({block:'start'});row.classList.add('active');}}});$('#closeReader').focus({preventScroll:true});if(updateHistory)updateRoute('#volume-'+book.volume+'-year-'+year+(anchor!==null?'-para-'+anchor:''));decoratePeople();updateProgress();if(!updateHistory)restorePeopleHistory();}
function closeReader(updateHistory=true){hidePeoplePage();if(updateHistory&&readerReturnState){const state=readerReturnState;if(book!==state.book)applyBook(state.book);period=state.period;eventFilter=state.eventFilter;$('#search').value=state.search;$('#searchScope').value=state.scope;$('#recordedOnly').checked=state.recordedOnly;yearbookScroll=state.scroll;render();}readerReturnState=null;readerOpen=false;document.title='资治通鉴 · '+bookLabel();$('#readerBackdrop').classList.add('hidden');$('#annualPage').classList.remove('hidden');document.body.style.overflow='';if(updateHistory)history.pushState({reading:false},'','#volume-'+book.volume);focusBefore?.focus({preventScroll:true});window.scrollTo({top:yearbookScroll,behavior:'instant'});}
function volumeIntro(updateHistory=true){hidePeoplePage();enterReadingPage();setReadingMode('original');$('#readerContent').innerHTML=`<div class="reader-title"><div class="eyebrow">卷首 · 原文</div><h2>${esc(bookLabel())}</h2><div class="reign-line">${esc(book.fullTitle||book.title)}</div></div><article class="original ${$('#showNotes').checked?'':'hide-notes'}">${paragraphs(book.intro)}</article>`;window.scrollTo({top:0,behavior:'instant'});$('#readerPosition').textContent='卷首说明';$('#prevYear').disabled=true;$('#nextYear').disabled=false;readingIndex=-1;$('#closeReader').focus({preventScroll:true});if(updateHistory)updateRoute('#volume-'+book.volume+'-intro');updateProgress();if(!updateHistory)restorePeopleHistory();}
$('#showNotes').onchange=()=>document.querySelectorAll('.original').forEach(x=>x.classList.toggle('hide-notes',!$('#showNotes').checked));$('#smaller').onclick=()=>{readingSize=Math.max(15,readingSize-1);document.documentElement.style.setProperty('--reading-size',readingSize+'px')};$('#larger').onclick=()=>{readingSize=Math.min(28,readingSize+1);document.documentElement.style.setProperty('--reading-size',readingSize+'px')};$('#search').oninput=searchChanged;$('#recordedOnly').onchange=render;$('#readerYear').onchange=e=>readYear(+e.target.value);$('#prevYear').onclick=()=>stepYear(-1);$('#nextYear').onclick=()=>stepYear(1);$('#closeReader').onclick=()=>returnFromReader();$('#volumeIntro').onclick=()=>{if(book)volumeIntro()};$('#about').onclick=()=>{fetch('coverage.json').then(r=>r.json()).then(c=>{$('#coverageSummary').textContent=`已收录${c.volumes}卷、${c.uniqueYears}个年份，${c.sourceBody}段原文正文。其中${c.matchedOriginal}段有上传译文对应，${c.unmatchedOriginal}段缺译或待核对。第${c.ancientOnlyVolumes.join('、')}卷的上传译本仅有古文。`;}).catch(()=>{});$('#infoBackdrop').classList.remove('hidden');$('#closeInfo').focus()};$('#closeInfo').onclick=()=>{$('#infoBackdrop').classList.add('hidden');$('#about').focus()};$('#infoBackdrop').onclick=e=>{if(e.target===$('#infoBackdrop'))$('#closeInfo').click()};function updateProgress(){if(!readerOpen)return;const start=$('#readerContent').getBoundingClientRect().top+window.scrollY;const available=document.documentElement.scrollHeight-window.innerHeight-start;const progress=available>0?Math.max(0,Math.min(100,(window.scrollY-start)/available*100)):100;$('#progressBar').style.width=progress+'%';}window.addEventListener('scroll',updateProgress,{passive:true});window.addEventListener('popstate',()=>routeFromHash());window.addEventListener('hashchange',()=>routeFromHash());

document.addEventListener('click',e=>{const row=e.target.closest('.compare-row');if(row){document.querySelectorAll('.compare-row').forEach(x=>x.classList.toggle('active',x===row));}const b=e.target.closest('button');if(!b||!book)return;if(b.dataset.readingMode){setReadingMode(b.dataset.readingMode);}if(b.dataset.eventFilter){eventFilter=b.dataset.eventFilter;resultLimit=50;render()}if(b.dataset.dynasty){const v=catalog.find(v=>v.dynasty===b.dataset.dynasty);if(v)changeVolume(v.volume)}if(b.dataset.period){period=b.dataset.period;document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x===b));render()}if(b.dataset.jump){selected=+b.dataset.jump;document.querySelectorAll('[data-jump]').forEach(x=>x.classList.toggle('active',x===b));$('#year-'+b.dataset.volume+'-'+selected)?.scrollIntoView({behavior:'smooth',block:'center'})}if(b.dataset.read)openYear(+(b.dataset.volume||book.volume),+b.dataset.read,b.dataset.anchor!==undefined?+b.dataset.anchor:null);if(b.id==='moreResults'){resultLimit+=50;render()}if(b.dataset.note){const next=b.nextElementSibling;if(next){next.style.display=next.style.display==='inline'?'':'inline';b.setAttribute('aria-expanded',next.style.display==='inline'?'true':'false')}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('compare-row')){e.preventDefault();document.querySelectorAll('.compare-row').forEach(x=>x.classList.toggle('active',x===e.target));}if(e.key==='Escape'){if(!$('#infoBackdrop').classList.contains('hidden'))$('#closeInfo').click();else if(!$('#peoplePage').classList.contains('hidden'))returnFromPeople();else if(readerOpen)returnFromReader()}if(e.key==='Tab'){const modal=!$('#infoBackdrop').classList.contains('hidden')?$('#infoBackdrop'):null;if(modal){const fs=[...modal.querySelectorAll('button:not(:disabled),input:not(:disabled),select,a,[tabindex="0"],summary')].filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===fs[0]){e.preventDefault();fs.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===fs.at(-1)){e.preventDefault();fs[0].focus()}}}});

function reportError(error){console.error(error);const target=readerOpen?$('#readerContent'):$('#chronicle');target.innerHTML='<div class="error">内容加载失败，请刷新重试。卷次与年份已保留在地址中。</div>';}
async function loadVolume(volume){if(booksCache.has(volume))return booksCache.get(volume);if(!catalog.some(v=>v.volume===volume))throw Error('Unknown volume');if(!pendingBooks.has(volume))pendingBooks.set(volume,fetch('volume'+volume+'.json').then(r=>{if(!r.ok)throw Error('Cannot load volume');return r.json()}).then(data=>{booksCache.set(volume,data);if(booksCache.size>5){const oldest=[...booksCache.keys()].find(v=>v!==volume&&v!==book?.volume);if(oldest!==undefined)booksCache.delete(oldest)}return data}).finally(()=>pendingBooks.delete(volume)));return pendingBooks.get(volume);}
function bookLabel(){return catalog.find(v=>v.volume===book.volume)?.title||book.title;}
function applyBook(data){const changed=book?.volume!==data.volume;book=data;if(changed){period='all';yearbookScroll=0;selected=book.years[0].year;$('#search').value='';}$('#volumeSelect').value=book.volume;$('#dynastySelect').value=book.years[0].dynasty||'周';document.querySelectorAll('[data-dynasty]').forEach(button=>{const active=button.dataset.dynasty===$('#dynastySelect').value;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});$('#volumeHeading').textContent='资治通鉴 / '+bookLabel();$('#yearCount').textContent=book.years.length;$('#recordedCount').textContent=book.years.filter(y=>y.recorded).length;$('#volumeCount').textContent=book.volume+' / '+catalog.length;$('#volumeRange').textContent=yearRange(book.years[0].year,book.years.at(-1).year);$('#volumeDescription').textContent=reign(book.years[0])+' → '+reign(book.years.at(-1));$('#readerBackdrop .reader-head .label').textContent=bookLabel()+' / 原文与白话对读';$('#readerYear').innerHTML=book.years.map(y=>`<option value="${y.year}">${yearLabel(y.year)}</option>`).join('');const kings=[...new Set(book.years.map(y=>y.king))];$('#periods').innerHTML=`<button class="${period==='all'?'active':''}" data-period="all">全部${book.years.length}年</button>`+kings.map(king=>`<button class="${period===king?'active':''}" data-period="${esc(king)}">${esc(king)}</button>`).join('');render();}
async function openYear(volume,year,anchor=null,updateHistory=true){if(!readerOpen&&book)readerReturnState={book,period,eventFilter,search:$('#search').value,scope:$('#searchScope').value,recordedOnly:$('#recordedOnly').checked,scroll:window.scrollY};const nav=++navigationId;try{const data=await loadVolume(volume);if(nav!==navigationId)return;if(!data.years.some(y=>y.year===year))throw Error('Unknown year');if(book!==data)applyBook(data);readYear(year,anchor,updateHistory);}catch(error){if(nav===navigationId)reportError(error);}}
async function changeVolume(volume,updateHistory=true){const nav=++navigationId;try{const data=await loadVolume(volume);if(nav!==navigationId)return;applyBook(data);closeReader(false);window.scrollTo({top:0,behavior:'instant'});if(updateHistory)updateRoute('#volume-'+volume);}catch(error){if(nav===navigationId)reportError(error);}}
function updateYearNavigation(){const hasPrev=readingIndex>0||book.volume>catalog[0].volume;const hasNext=readingIndex<book.years.length-1||book.volume<catalog.at(-1).volume;$('#prevYear').disabled=!hasPrev;$('#nextYear').disabled=!hasNext;$('#prevYear').textContent=readingIndex===0&&hasPrev?(catalog.find(v=>v.volume===book.volume-1)?.end===selected?'← 本年上篇':'← 上一年 · 上一卷'):'← 上一年';$('#nextYear').textContent=readingIndex===book.years.length-1&&hasNext?(catalog.find(v=>v.volume===book.volume+1)?.start===selected?'本年续篇 →':'下一年 · 下一卷 →'):'下一年 →';$('#readerPosition').textContent='卷 '+book.volume+' · '+(readingIndex+1)+' / '+book.years.length+' 年';document.title=yearLabel(book.years[readingIndex].year)+' · 资治通鉴';}
async function stepYear(direction){const next=readingIndex+direction;if(next>=0&&next<book.years.length){readYear(book.years[next].year);return;}const volume=book.volume+direction;const meta=catalog.find(v=>v.volume===volume);if(meta)await openYear(volume,direction<0?meta.end:meta.start);}
async function routeFromHash(){const hash=location.hash;if(await routePeopleHash(hash))return;hidePeoplePage();let m=hash.match(/^#volume-(\d+)-year-(-?\d+)(?:-para-(\d+))?$/);if(m){await openYear(+m[1],+m[2],m[3]!==undefined?+m[3]:null,false);return;}m=hash.match(/^#year-(-?\d+)$/);if(m){const meta=catalog.find(v=>v.start>=+m[1]&&v.end<=+m[1]);if(meta){await openYear(meta.volume,+m[1],null,false);return;}}m=hash.match(/^#volume-(\d+)(-intro)?$/);const volume=m?+m[1]:1;const nav=++navigationId;try{const data=await loadVolume(volume);if(nav!==navigationId)return;applyBook(data);if(m?.[2]||hash==='#volume-intro')volumeIntro(false);else{closeReader(false);document.title='资治通鉴 · '+book.title;restorePeopleHistory();}}catch(error){if(nav===navigationId)reportError(error);}}
function yearParts(y){const volumes=yearVolumes[y.year]||[book.volume];if(volumes.length<2)return '';return `<div class="year-note">本年记事分见 ${volumes.length} 卷：${volumes.map(v=>v===book.volume?`第${v}卷（当前）`:`<button class="part-link" data-volume="${v}" data-read="${y.year}">第${v}卷 →</button>`).join(' · ')}。按原书卷次分别保留，可接续阅读。</div>`;}
function unparsedTranslation(y){if(!y.translationBlocks?.length)return '';return `<details class="source-differences"><summary>译本所载内容待核对 · 展开原文件</summary><div class="difference-body">${esc(y.translationWarning||'这部分原文与白话的边界待核对，保留源内容。')}${y.translationBlocks.map(t=>`<p>${esc(t)}</p>`).join('')}</div></details>`;}
let searchId=0;function searchChanged(){const id=++searchId;clearTimeout(searchTimer);resultLimit=50;const q=$('#search').value.trim().toLowerCase();if($('#searchScope').value!=='all'||!q){fullSearchHits=[];searchComplete=true;searchWorker?.postMessage({type:'cancel'});render();return;}fullSearchHits=[];searchComplete=false;searchChecked=0;render();searchTimer=setTimeout(()=>{if(id!==searchId)return;if(!searchWorker){try{searchWorker=new Worker('search-worker.js');searchWorker.onmessage=e=>{const m=e.data;if(m.id!==searchId)return;if(m.error){searchComplete=true;$('#chronicle').innerHTML='<div class="error">全书搜索部分文件加载失败，请重试。</div>';return;}fullSearchHits=m.hits;searchChecked=m.checked;searchComplete=m.complete;render();};searchWorker.onerror=()=>{$('#chronicle').innerHTML='<div class="error">全书搜索暂不可用，可切换本卷搜索。</div>';};}catch(error){reportError(error);return;}}searchWorker.postMessage({type:'search',id,q,volumes:catalog.map(v=>v.volume)});},350);}
function selectOptions(){const dynasties=[...new Set(catalog.map(v=>v.dynasty||'周'))];$('#dynastyTabs').innerHTML=dynasties.map(d=>`<button data-dynasty="${esc(d)}" aria-pressed="false">${esc(d)}</button>`).join('');$('#volumeSelect').innerHTML=dynasties.map(d=>`<optgroup label="${esc(d)}">${catalog.filter(v=>(v.dynasty||'周')===d).map(v=>`<option value="${v.volume}">${esc(v.title)} · ${yearRange(v.start,v.end)}</option>`).join('')}</optgroup>`).join('');$('#dynastySelect').innerHTML='<option value="">按朝代跳转</option>'+dynasties.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('');}
$('#dynastySelect').onchange=e=>{const v=catalog.find(v=>v.dynasty===e.target.value);if(v)changeVolume(v.volume);};$('#jumpYearForm').onsubmit=e=>{e.preventDefault();const value=Number($('#jumpYearInput').value);if(!Number.isInteger(value)||value<1){$('#jumpYearStatus').textContent='请输入大于0的年份。';return;}const key=$('#jumpYearEra').value==='bce'?value:-value;const volumes=yearVolumes[key];if(!volumes?.length){$('#jumpYearStatus').textContent='收录前403年至959年，公历没有0年。';return;}$('#jumpYearStatus').textContent='';openYear(volumes[0],key);};
$('#searchScope').onchange=searchChanged;$('#volumeSelect').onchange=e=>changeVolume(+e.target.value);
fetch('catalog.json').then(r=>{if(!r.ok)throw Error('Cannot load catalog');return r.json()}).then(async data=>{catalog=data.volumes;yearVolumes=data.yearVolumes||{};await loadPeopleIndex();selectOptions();return routeFromHash();}).catch(reportError);
